var bauhaus_default = `/* SPDX-License-Identifier: AGPL-3.0-or-later */
/* Copyright (c) 2026 Jessica Birky */

/* The Bauhaus theme's stylesheet: what it adds to its colors and its font
   (utils/themes.js). It's scoped to .deck-theme-bauhaus, a class on the
   editor's canvas and thumbnails, the presented deck's .reveal and the PDF's
   pages, so a slide looks the same in all of them. The editor loads it with
   the app (main.jsx); presented decks and the PDF write it into their page
   (utils/themeCss.js), after their own styles and before the deck's custom
   CSS. Presented decks are drawn on reveal.js's white theme. */

/* reveal.js: links, the arrows and the progress bar in red */
.deck-theme-bauhaus {
  --r-background-color: #f7f6f2;
  --r-main-color: #151515;
  --r-heading-color: #151515;
  --r-link-color: #d52b1e;
  --r-link-color-dark: #a51f15;
  --r-link-color-hover: #a51f15;
  --r-selection-background-color: #d52b1e;
  --r-selection-color: #f7f6f2;
}

/* Headings in lowercase, after Herbert Bayer's universal alphabet (1925),
   set a little tight. (!important: presented decks reset headings' case and
   spacing with it.) */
.deck-theme-bauhaus :is(h1, h2, h3, h4, h5, h6) {
  text-transform: lowercase !important;
  letter-spacing: -0.02em !important;
}

/* A short red rule under slide titles (Heading 2), on the side the title is
   aligned to */
.deck-theme-bauhaus h2::after {
  content: "";
  display: block;
  width: 1.1em;
  height: 0.12em;
  margin-top: 0.22em;
  background: #d52b1e;
}
.deck-theme-bauhaus h2[style*="text-align: center"]::after { margin-left: auto; margin-right: auto; }
.deck-theme-bauhaus h2[style*="text-align: right"]::after { margin-left: auto; }

/* Square red bullets */
.deck-theme-bauhaus ul { list-style-type: square; }
.deck-theme-bauhaus li::marker { color: #d52b1e; }

/* Quotes behind a thick red bar */
.deck-theme-bauhaus blockquote {
  border-left: 0.2em solid #d52b1e !important;
  opacity: 1 !important;
}

/* Inline code as a square gray block on the white page */
.deck-theme-bauhaus :not(pre) > code {
  background: rgba(21, 21, 21, 0.08) !important;
  border-radius: 0 !important;
}

/* The theme's picture in the Themes panel (components/ThemeGallery.jsx) */
.deck-theme-bauhaus .theme-swatch-title {
  text-transform: lowercase;
  letter-spacing: -0.02em;
}
`;

// raw:client/src/themes/pixel.css
var pixel_default = `/* SPDX-License-Identifier: AGPL-3.0-or-later */
/* Copyright (c) 2026 Jessica Birky */

/* The Pixel theme's stylesheet: an 8-bit look on top of its colors and
   fonts (utils/themes.js: Pixelify Sans for text, Press Start 2P for
   headings at one weight, which the Themes panel's Text tab can change).
   It's scoped to .deck-theme-pixel, a class on the editor's canvas and
   thumbnails, the presented deck's .reveal and the PDF's pages, so a slide
   looks the same in all of them. The editor loads it with the app
   (main.jsx); presented decks and the PDF write it into their page
   (utils/themeCss.js). Presented decks are drawn on reveal.js's black theme. */

/* reveal.js: links, the arrows and the progress bar in mint */
.deck-theme-pixel {
  --r-background-color: #14112e;
  --r-main-color: #f3eedf;
  --r-heading-color: #ffcc33;
  --r-link-color: #39e5c0;
  --r-link-color-dark: #2bb89a;
  --r-link-color-hover: #ffcc33;
  --r-selection-background-color: #8a6cff;
  --r-selection-color: #f3eedf;
}

/* Headings in capitals, with a hard purple drop shadow and no smoothing.
   (!important: presented decks reset headings' case, spacing and shadow
   with it.) */
.deck-theme-pixel :is(h1, h2, h3, h4, h5, h6) {
  text-transform: uppercase !important;
  letter-spacing: 0 !important;
  line-height: 1.3;
  text-shadow: 0.125em 0.125em 0 #8a6cff !important;
  -webkit-font-smoothing: none;
}

/* Arrow bullets in gold */
.deck-theme-pixel ul { list-style-type: "▸  "; }
.deck-theme-pixel li::marker { color: #ffcc33; }

/* Quotes behind a mint bar */
.deck-theme-pixel blockquote {
  border-left: 0.15em solid #39e5c0 !important;
  opacity: 1 !important;
}

/* Inline code in VT323, mint on the panel color */
.deck-theme-pixel :not(pre) > code {
  font-family: VT323, monospace !important;
  font-size: 1.2em;
  color: #39e5c0;
  background: #231e52 !important;
  border-radius: 0 !important;
  padding: 0 0.25em;
}

/* The theme's picture in the Themes panel (components/ThemeGallery.jsx) */
.deck-theme-pixel .theme-swatch-title {
  text-transform: uppercase;
  text-shadow: 0.125em 0.125em 0 #8a6cff;
}
`;

// raw:client/src/themes/mission.css
var mission_default = `/* SPDX-License-Identifier: AGPL-3.0-or-later */
/* Copyright (c) 2026 Jessica Birky */

/* The Mission theme's stylesheet: an engineering drawing on top of its
   colors and fonts (utils/themes.js: IBM Plex Sans for text, Barlow Condensed
   for headings, which the Themes panel's Text tab can change). It's scoped
   to .deck-theme-mission, a class on the editor's canvas and thumbnails, the
   presented deck's .reveal and the PDF's pages, so a slide looks the same in
   all of them. The editor loads it with the app (main.jsx); presented decks
   and the PDF write it into their page (utils/themeCss.js). Presented decks
   are drawn on reveal.js's white theme. The drafting grid is the theme's
   page (its backgroundCss) in the editor and the PDF. */

/* reveal.js: links, the arrows and the progress bar in telemetry blue */
.deck-theme-mission {
  --r-background-color: #f4f6f8;
  --r-main-color: #0d1b2e;
  --r-heading-color: #0d1b2e;
  --r-link-color: #1d6fd1;
  --r-link-color-dark: #1557a6;
  --r-link-color-hover: #e4462b;
  --r-selection-background-color: #1d6fd1;
  --r-selection-color: #f4f6f8;
}

/* The drafting grid on presented slides that show the theme's page */
.deck-theme-mission .slides > section:not([data-background-color]):not([data-background-image]):not([data-background-gradient]) {
  background:
    linear-gradient(#dde3ea 1px, transparent 1px) 0 0 / 60px 60px,
    linear-gradient(90deg, #dde3ea 1px, transparent 1px) 0 0 / 60px 60px,
    linear-gradient(#e9edf2 1px, transparent 1px) 0 0 / 12px 12px,
    linear-gradient(90deg, #e9edf2 1px, transparent 1px) 0 0 / 12px 12px,
    #f4f6f8;
}

/* Headings in capitals, a little tracked, like drawing lettering. (!important:
   presented decks reset headings' case and spacing with it.) */
.deck-theme-mission :is(h1, h2, h3, h4, h5, h6) {
  text-transform: uppercase !important;
  letter-spacing: 0.01em !important;
  line-height: 1.05;
}

/* A hairline under slide titles (Heading 2), the width of their box */
.deck-theme-mission h2::after {
  content: "";
  display: block;
  height: 1px;
  margin-top: 0.22em;
  background: #0d1b2e;
}

/* Square bullets in signal red */
.deck-theme-mission ul { list-style-type: square; }
.deck-theme-mission li::marker { color: #e4462b; }

/* Quotes behind an ink bar */
.deck-theme-mission blockquote {
  border-left: 0.12em solid #0d1b2e !important;
  opacity: 1 !important;
}

/* Inline code in B612 Mono, the cockpit-display face, on a square gray block */
.deck-theme-mission :not(pre) > code {
  font-family: 'B612 Mono', monospace !important;
  font-size: 0.9em;
  color: #0d1b2e;
  background: #e3e9ef !important;
  border-radius: 0 !important;
  padding: 0 0.3em;
}

/* The theme's picture in the Themes panel (components/ThemeGallery.jsx) */
.deck-theme-mission .theme-swatch-title {
  text-transform: uppercase;
}
`;

